window.SCHOOL_LISTENING={"../assets/media/7fe3e7ea6da39fe91f3a39672de7968448a8071e749c2f0515c470ceafca37b0.mp3":[{"id":"PPT_7fe3e7ea6da39fe9","audioId":"PPT_7fe3e7ea6da39fe9","title":"Book 2 · Unit 2 · RW · READING 1","subtitle":"READING 1 · source slide 50","duration":185.39,"cues":[{"start":1.04,"end":1.84,"text":"celebrate","coverage":1},{"start":3.24,"end":4.04,"text":"Pinatas","coverage":1},{"start":4.58,"end":9.2,"text":"In Mexico, people often have pinatas at their parties.","coverage":1},{"start":9.9,"end":15.6,"text":"Parents put chocolates and other sweets inside the pinata and hang it on a tree.","coverage":1},{"start":16.36,"end":18.84,"text":"Children hit the pinata with a stick.","coverage":1},{"start":19.4,"end":23.22,"text":"It breaks and the sweets fall out onto the ground.","coverage":1},{"start":25.44,"end":26,"text":"Noodles","coverage":1},{"start":26.52,"end":27.86,"text":"In China,","coverage":1},{"start":28.24,"end":37.08,"text":"people celebrate weddings with an eight course meal, because the word eight in Chinese sounds like the word for good luck.","coverage":1},{"start":38.06,"end":41.46,"text":"The last dish of the meal is always noodles.","coverage":1},{"start":42.12,"end":44.46,"text":"The noodles are long and thin.","coverage":1},{"start":45.24,"end":47.52,"text":"You have to eat them in one piece.","coverage":1},{"start":47.84,"end":49.12,"text":"You can't cut them.","coverage":1},{"start":49.88,"end":51.32,"text":"In Chinese culture,","coverage":1},{"start":51.8,"end":53.44,"text":"long noodles are lucky.","coverage":1},{"start":53.44,"end":57.86,"text":"Long noodles mean you will have a long life.","coverage":1},{"start":60.24,"end":61.16,"text":"Mother's Day","coverage":1},{"start":61.68,"end":66.66,"text":"Many people around the world honor their mothers on Mother's Day.","coverage":1},{"start":67.2,"end":68.2,"text":"In the UK,","coverage":1},{"start":68.72,"end":72.3,"text":"Mother's Day is celebrated in March or April.","coverage":1},{"start":73.16,"end":77.2,"text":"Sons and daughters like to give their mother a day to rest,","coverage":1},{"start":77.52,"end":83.04,"text":"so they might surprise her by cleaning the house or cooking a nice meal for her.","coverage":1},{"start":83.04,"end":87.76,"text":"They also give her gifts such as flowers or jewelry.","coverage":1},{"start":88.78,"end":93.5,"text":"Many families take their mother to a restaurant for lunch or dinner.","coverage":1},{"start":95.42,"end":97.12,"text":"New Year's Eve","coverage":1},{"start":97.64,"end":101.66,"text":"London celebrates New Year's Eve in a big way.","coverage":1},{"start":102.3,"end":107.47,"text":"Thousands of people go to the River Thames and then when it is dark outside,","coverage":1},{"start":108.36,"end":114.36,"text":"fireworks light up the sky and Big Ben, the bell in London's famous clock tower,","coverage":1},{"start":114.68,"end":115.8,"text":"chimes at midnight.","coverage":1},{"start":116.78,"end":121.48,"text":"The next day, people eat a big meal with family and friends,","coverage":1},{"start":121.82,"end":125.34,"text":"go for a walk or just relax at home.","coverage":1},{"start":127.44,"end":128.72,"text":"Coming of Age Day","coverage":1},{"start":129.4,"end":130.44,"text":"In Japan,","coverage":1},{"start":130.78,"end":135.54,"text":"people celebrate Coming of Age Day or Seijin Nohi","coverage":1},{"start":135.94,"end":138.64,"text":"on the second Monday in January.","coverage":1},{"start":139.36,"end":140.88,"text":"On this holiday,","coverage":1},{"start":141.62,"end":154.08,"text":"Japan congratulates people who have turned or will turn 20 years old between the second of April of the past year and the first of April of the current year.","coverage":1},{"start":154.88,"end":163.92,"text":"In Japanese culture, this is the age when teenagers become adults and take on the responsibilities of being an adult.","coverage":1},{"start":164.72,"end":169.64,"text":"Young women usually wear a traditional furisode kimono,","coverage":1},{"start":170.24,"end":173.5,"text":"while young men often wear Western -style suits,","coverage":1},{"start":174.24,"end":177.54,"text":"and they attend a ceremony in their area.","coverage":1},{"start":178.26,"end":183.46,"text":"They receive small presents and celebrate with their friends after the ceremony.","coverage":1}],"file":"83a614c3701dbb982eab.js","track":0,"media":"../assets/media/7fe3e7ea6da39fe91f3a39672de7968448a8071e749c2f0515c470ceafca37b0.mp3"}],"../assets/media/88e42fe186792f3ab40eda3dfb791dc2019d89a8cf7a1f3314ebf7ce7bd0aff7.mp3":[{"id":"PPT_88e42fe186792f3a","audioId":"PPT_88e42fe186792f3a","title":"Book 2 · Unit 2 · RW · READING 2","subtitle":"READING 2 · source slide 78","duration":118.88,"cues":[{"start":0,"end":7.04,"text":"Muscat Nights One of the most important festivals in Oman is Muscat Nights.","coverage":1},{"start":7.56,"end":12.34,"text":"The festival lasts for about one month and takes place in February every year.","coverage":1},{"start":13.1,"end":14.12,"text":"During the festival,","coverage":1},{"start":14.5,"end":18.18,"text":"many activities are available for people to take part in.","coverage":1},{"start":18.96,"end":20.24,"text":"Large numbers of people,","coverage":1},{"start":20.58,"end":23.56,"text":"including local Omanis and visitors to Oman,","coverage":1},{"start":24.04,"end":25.3,"text":"go to the different events.","coverage":1},{"start":25.3,"end":31.78,"text":"The events are a celebration of both Omani and international history and traditions.","coverage":1},{"start":32.82,"end":35.64,"text":"The events happen in different places across the country.","coverage":1},{"start":36.44,"end":40.64,"text":"Many businesses show their products for people to look at and buy.","coverage":1},{"start":42.1,"end":48.54,"text":"Muscat Nights also includes the very popular Six -Day Tour of Oman Cycle Race.","coverage":1},{"start":49.52,"end":52.96,"text":"Professional cyclists from around the world take part in the race.","coverage":1},{"start":52.96,"end":61.3,"text":"The race is one ,000 kilometers long and it takes the cyclists up the beautiful Jabal al -Aqdar, the Green Mountain.","coverage":1},{"start":62.58,"end":68.06,"text":"Other highlights of Muscat Nights include the chance to experience different food and music.","coverage":1},{"start":68.76,"end":69.52,"text":"For example,","coverage":1},{"start":69.88,"end":73.66,"text":"you can taste traditional types of food at the Oman Food Festival.","coverage":1},{"start":74.62,"end":79.86,"text":"The Muscat Art Festival also offers Arabic music, concerts and plays,","coverage":1},{"start":80.38,"end":82.72,"text":"and other entertainment for the whole family.","coverage":1},{"start":82.72,"end":88.66,"text":"The Festival of Lights is one of the most popular events at Muscat Nights.","coverage":1},{"start":90.08,"end":92.56,"text":"Muscat Nights is an international event,","coverage":1},{"start":93,"end":97.36,"text":"with people visiting from countries as far away as Brazil and Cuba.","coverage":1},{"start":98.46,"end":100.5,"text":"Visitors also arrive from Italy,","coverage":1},{"start":100.82,"end":101.3,"text":"India,","coverage":1},{"start":101.72,"end":102.12,"text":"Russia,","coverage":1},{"start":102.54,"end":103.24,"text":"South Korea,","coverage":1},{"start":103.62,"end":104.02,"text":"Spain,","coverage":1},{"start":104.5,"end":106.1,"text":"Tunisia and Turkey,","coverage":1},{"start":106.46,"end":108.2,"text":"as well as many other countries.","coverage":1},{"start":108.2,"end":110.94,"text":"They enjoy the amazing clothes,","coverage":1},{"start":111.32,"end":112.78,"text":"food and music.","coverage":1},{"start":113.7,"end":116.94,"text":"Some people just enjoy the mix of different cultures.","coverage":1}],"file":"f0d09209130e6d846381.js","track":0,"media":"../assets/media/88e42fe186792f3ab40eda3dfb791dc2019d89a8cf7a1f3314ebf7ce7bd0aff7.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1  The newspaper provided media coverage of the event.","slide":9,"shape":"8","bookPage":"38"},{"text":"2  People walked through the streets in a procession.","slide":9,"shape":"9","bookPage":"38"},{"text":"3  He carried a burning torch.","slide":9,"shape":"10","bookPage":"38"},{"text":"4  I regret not going to the celebration.","slide":9,"shape":"11","bookPage":"38"},{"text":"5  This festival is unique; there is nothing else like it.","slide":9,"shape":"12","bookPage":"38"},{"text":"Are parties, fireworks, midnight and processions part of New Year’s celebrations in your country? What happens?Possible answer: In my town, families have parties and watch fireworks at midnight.","slide":11,"shape":"15","bookPage":"38"},{"text":"What do you know about New Year’s celebrations in other countries?Possible answer: People in London watch fireworks near the River Thames.","slide":11,"shape":"16","bookPage":"38"},{"text":"Look at the photos and describe what you can see in each one.Possible answer: Photo 1: Fireworks light up the London Eye. Photo 2: A large crowd is waiting outside.","slide":13,"shape":"15","bookPage":"38"},{"text":"Crowds of people watch fireworks at midnight. Write L, E or B.Correct answer: B — both London and Edinburgh","slide":20,"shape":"17","bookPage":"39"},{"text":"People wait for a long time by the river. Write L, E or B.Correct answer: L — London","slide":20,"shape":"18","bookPage":"39"},{"text":"People walk in a line through the city. Write L, E or B.Correct answer: E — Edinburgh","slide":20,"shape":"19","bookPage":"39"},{"text":"12,000: match to a–d.Correct answer: d — fireworks in London","slide":20,"shape":"5","bookPage":"39"},{"text":"100,000: match to a–d.Correct answer: c — people watched by the River Thames","slide":21,"shape":"17","bookPage":"39"},{"text":"three days: match to a–d.Correct answer: a — how long Hogmanay lasts","slide":21,"shape":"18","bookPage":"39"},{"text":"8,000: match to a–d.Correct answer: b — people in the procession in Edinburgh","slide":21,"shape":"19","bookPage":"39"},{"text":"It was a cloudy night in London. Write T or F and correct false statements.Correct answer: False. It was a clear night in London.","slide":21,"shape":"5","bookPage":"39"},{"text":"The woman from Buenos Aires was pleased she came to London. Write T or F.Correct answer: True.","slide":22,"shape":"12","bookPage":"39"},{"text":"In Edinburgh, people threw fireworks in the streets. Write T or F and correct false statements.Correct answer: False. People carried torches in the streets.","slide":22,"shape":"13","bookPage":"39"},{"text":"Discuss what “looking backwards” means in “A time for looking backwards, looking forwards and for looking up.”Possible answer: Thinking about the year that has finished.","slide":24,"shape":"15","bookPage":"39"},{"text":"Discuss what “looking forwards and looking up” means in the expression.Possible answer: Thinking about the new year; looking at the fireworks in the sky.","slide":24,"shape":"16","bookPage":"39"},{"text":"Have you ever been part of a procession? If yes, when, why and what was it like?Possible answer: I joined a lantern procession last year. It was colourful and exciting.","slide":26,"shape":"15","bookPage":"39"},{"text":"Why, do you think, are fireworks popular for festivals and celebrations?Possible answer: Fireworks bring people together.","slide":26,"shape":"16","bookPage":"39"},{"text":"Is New Year about looking backwards or forwards? Why?Possible answer: New Year is about both remembering the past and making plans.","slide":26,"shape":"17","bookPage":"39"},{"text":"In Japanese culture, which number is lucky because its written shape looks like something growing?a 8 b 9Correct answer: a 8","slide":37,"shape":"16","bookPage":"40"},{"text":"How do people celebrate New Year’s Eve in Spain?a They break 12 plates. b They eat 12 grapes.Correct answer: b They eat 12 grapes.","slide":37,"shape":"17","bookPage":"40"},{"text":"What does the bride put in her glove at a traditional Greek wedding?a money b sugarCorrect answer: b sugar","slide":37,"shape":"18","bookPage":"40"},{"text":"In which country can you see colourful fireworks on 4 July?a The United States b IndiaCorrect answer: a The United States","slide":38,"shape":"10","bookPage":"40"},{"text":"At Chinese New Year, what special gift do families give each other?a red flowers b money in red envelopesCorrect answer: b money in red envelopes","slide":38,"shape":"11","bookPage":"40"},{"text":"to do something enjoyable because it is a special occasionCorrect answer: celebrate","slide":38,"shape":"12","bookPage":"40"},{"text":"the habits, traditions and beliefs of a countryCorrect answer: culture","slide":38,"shape":"5","bookPage":"40"},{"text":"small objects which explode to make noise and bright coloursCorrect answer: fireworks","slide":39,"shape":"10","bookPage":"40"},{"text":"something that you give to somebodyCorrect answer: gift","slide":39,"shape":"11","bookPage":"40"},{"text":"causing good things to happenCorrect answer: lucky","slide":39,"shape":"12","bookPage":"40"},{"text":"following ways of behaving that have continued for a long timeCorrect answer: traditional","slide":39,"shape":"5","bookPage":"40"},{"text":"Look at the photos, title and subtitles. Circle the topic.a celebrations around the worldb weddings around the worldCorrect answer: a celebrations around the world","slide":44,"shape":"15","bookPage":"41"},{"text":"1  The bell chimes at midnight.","slide":49,"shape":"7","bookPage":"41"},{"text":"2  Young adults take on new responsibilities.","slide":49,"shape":"8","bookPage":"41"},{"text":"3  People attend a formal ceremony.","slide":49,"shape":"9","bookPage":"41"},{"text":"use a stick to get sweetsCorrect answer: Mexico","slide":58,"shape":"16","bookPage":"42"},{"text":"eat long noodlesCorrect answer: China","slide":58,"shape":"17","bookPage":"42"},{"text":"watch the fireworksCorrect answer: the UK","slide":58,"shape":"18","bookPage":"42"},{"text":"Piñatas have flowers inside them. Write T or F and correct false statements.Correct answer: False. Piñatas have chocolates and other sweets inside them.","slide":58,"shape":"5","bookPage":"42"},{"text":"Long noodles are unlucky in Chinese culture. Write T or F and correct false statements.Correct answer: False. Long noodles are lucky in Chinese culture.","slide":59,"shape":"13","bookPage":"42"},{"text":"Mother’s Day in the UK is in June or July. Write T or F and correct false statements.Correct answer: False. Mother’s Day in the UK is in March or April.","slide":59,"shape":"14","bookPage":"42"},{"text":"On New Year’s Day, some people eat with family and friends. Write T or F.Correct answer: True.","slide":59,"shape":"15","bookPage":"42"},{"text":"Where would you find this article?a in a magazine b in an academic journalCorrect answer: a in a magazine","slide":62,"shape":"14","bookPage":"42"},{"text":"Which features helped you find the answer?Possible answer: The colourful design, photographs and short sections suggest a magazine.","slide":62,"shape":"15","bookPage":"42"},{"text":"1. Summary gap 1\nAnswer: meal","slide":65,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nAnswer: iii","slide":65,"shape":"8","bookPage":null},{"text":"Hi,I promised I’d write and tell you about how my family celebrated Diwali this year. As you know, the (1) history of Diwali goes back hundreds of years. This year there was a big celebration in the park. Lots of people came, including local people and (2) visitors.","slide":76,"shape":"17","bookPage":"43"},{"text":"At the event, there was traditional music and food. The food was (3) popular because it was delicious and cheap. There were some (4) activities for children, like making coloured lanterns. There was a race in the afternoon, and I decided to (5) take part. I’m glad I did because I won!","slide":76,"shape":"18","bookPage":"43"},{"text":"For me, the fireworks at night were the (6) highlight of the event. They were amazing! Love, Meera","slide":77,"shape":"17","bookPage":"43"},{"text":"1 One of the most important festivals in Oman is Muscat Nights. The festival lasts for about one month and takes place in February every year. During the festival, many activities are available for people to take part in.","slide":85,"shape":"11","bookPage":"43"},{"text":"People from many different countries come to the event. Paragraph 5","slide":88,"shape":"16","bookPage":"45"},{"text":"The different things that visitors to Muscat Nights can do. Paragraph 4","slide":88,"shape":"17","bookPage":"45"},{"text":"Muscat Nights is in the month of February.Correct answer: Supported by the text.","slide":88,"shape":"18","bookPage":"45"},{"text":"The Tour of Oman is a six-day event.Correct answer: Supported by the text.","slide":88,"shape":"5","bookPage":"45"},{"text":"Cyclists race for 1,000 kilometres.Correct answer: Supported by the text.","slide":88,"shape":"6","bookPage":"45"},{"text":"The English name for Jabal Al Akhdar is the Green Mountain.Correct answer: Supported by the text.","slide":89,"shape":"13","bookPage":"45"},{"text":"5 The Festival of Lights is popular with adults and children.Correction: The Festival of Lights is one of the most popular events at Muscat Nights.","slide":89,"shape":"14","bookPage":"45"},{"text":"Visitors like the food and music.Correct answer: Supported by the text.","slide":89,"shape":"5","bookPage":"45"},{"text":"What type of text is this?a a news articleb an academic essayc an article from a cultural websiteCorrect answer: c an article from a cultural website","slide":97,"shape":"14","bookPage":"45"},{"text":"Who is the text for?a students b tourists c teachersCorrect answer: b tourists","slide":97,"shape":"15","bookPage":"45"},{"text":"We had a big family meal on Friday.","slide":101,"shape":"16","bookPage":"46"},{"text":"My cousin took part in the Tour of Oman cycle race in February.","slide":101,"shape":"17","bookPage":"46"},{"text":"We will go to the concert at the weekend.","slide":101,"shape":"18","bookPage":"46"},{"text":"I will meet you at the train station.","slide":101,"shape":"5","bookPage":"46"},{"text":"There are a lot of traditional festivals in Japan.","slide":101,"shape":"6","bookPage":"46"},{"text":"Write a sentence about where the food festival is.Correct answer: The festival is in Athens.","slide":104,"shape":"14","bookPage":"46"},{"text":"Write a sentence about when the food festival is.Correct answer: The festival is in May.","slide":104,"shape":"15","bookPage":"46"},{"text":"Write a sentence about cooking sessions.Correct answer: The cooking sessions are on Saturdays at the Theatre.","slide":104,"shape":"16","bookPage":"46"},{"text":"Write a sentence about live music.Correct answer: The live music starts at 19:00 in the Park.","slide":104,"shape":"17","bookPage":"46"},{"text":"In China, people never cut their noodles at a wedding.","slide":114,"shape":"13","bookPage":"47"},{"text":"Children in the UK sometimes clean the house or cook a meal on Mother’s Day.","slide":114,"shape":"14","bookPage":"47"},{"text":"Families in the UK often / usually take their mother to a restaurant on Mother’s Day.","slide":114,"shape":"15","bookPage":"47"},{"text":"In London, fireworks always light up the night sky on New Year’s Eve.","slide":114,"shape":"5","bookPage":"47"},{"text":"Write three true sentences about celebrations using adverbs of frequency.Possible answer: I usually visit my family at New Year. We sometimes give gifts on special occasions. I am always happy at family weddings.","slide":116,"shape":"12","bookPage":"47"},{"text":"The parade starts on Saturday.","slide":120,"shape":"6","bookPage":null},{"text":"Visitors watch fireworks at night.","slide":120,"shape":"9","bookPage":null},{"text":"Our town has a food festival in May. The festival has a cake stall. Its cakes are popular with visitors.","slide":121,"shape":"6","bookPage":null},{"text":"The parade begins at noon. After the parade, people watch a dance show. The show ends before dinner.","slide":122,"shape":"6","bookPage":null},{"text":"The children are making paper decorations. They are working together at a school celebration.","slide":123,"shape":"7","bookPage":null},{"text":"The children are using paper for their decorations. They are at a school event.","slide":124,"shape":"7","bookPage":null},{"text":"1. People needed tickets for the first festival.\nAnswer: FALSE","slide":129,"shape":"5","bookPage":null},{"text":"11. Residents influence the choice between two types of entertainment.\nAnswer: B","slide":129,"shape":"8","bookPage":null},{"text":"1. Summary gap 1\nAnswer: kitchens","slide":132,"shape":"5","bookPage":null},{"text":"11. Paragraph A\nAnswer: vii","slide":132,"shape":"8","bookPage":null},{"text":"Our family never misses the annual parade.","slide":141,"shape":"6","bookPage":null},{"text":"The visitors usually meet at the main gate.","slide":141,"shape":"9","bookPage":null},{"text":"The winter festival opens in the old square. The square has several light displays. Visitors photograph these displays after dark.","slide":142,"shape":"6","bookPage":null},{"text":"The village holds a traditional food day. On that day, families cook local dishes. They share those dishes at a long table.","slide":143,"shape":"6","bookPage":null},{"text":"Two food stalls are open at the event. A family is looking at the food. They have several dishes to choose from.","slide":144,"shape":"7","bookPage":null},{"text":"The family can choose a dish at one stall. Then they can sit together and eat. This is a simple festival activity for visitors.","slide":145,"shape":"7","bookPage":null},{"text":"Muscat Nights","slide":155,"shape":"7","bookPage":"48"},{"text":"Oman","slide":155,"shape":"11","bookPage":"48"},{"text":"taste traditional foodTour of Oman cycle racemusic, concerts and playsFestival of Lights","slide":155,"shape":"13","bookPage":"48"},{"text":"February every year","slide":155,"shape":"15","bookPage":"48"},{"text":"Large numbers of peopleLocal OmanisInternational visitors","slide":155,"shape":"17","bookPage":"48"},{"text":"School culture festival","slide":160,"shape":"7","bookPage":"49"},{"text":"Food and drinks fromdifferent countries","slide":160,"shape":"9","bookPage":"49"},{"text":"At our school","slide":160,"shape":"11","bookPage":"49"},{"text":"Watch performancesPlay traditional gamesShare stories","slide":160,"shape":"13","bookPage":"49"},{"text":"A Saturday in May","slide":160,"shape":"15","bookPage":"49"},{"text":"Students and families","slide":160,"shape":"17","bookPage":"49"},{"text":"1. The children wear traditional clothes.Subject: The children; verb: wear.","slide":166,"shape":"16","bookPage":"50"},{"text":"2. My family and I watch the fireworks.Subject: My family and I; verb: watch.","slide":166,"shape":"18","bookPage":"50"},{"text":"3. I visit my aunt and uncle.Subject: I; verb: visit.","slide":166,"shape":"6","bookPage":"50"},{"text":"4. People in the UK usually celebrate university graduation.Subject: People in the UK; verb: celebrate.","slide":167,"shape":"13","bookPage":"50"},{"text":"5. We bought a gift for our parents’ anniversary.Subject: We; verb: bought.","slide":167,"shape":"15","bookPage":"50"},{"text":"1. My family eat at home. The words after the verb are at home — P (prepositional phrase).","slide":169,"shape":"13","bookPage":"50"},{"text":"2. The wedding costumes are beautiful. The words after the verb are beautiful — A (adjective).","slide":169,"shape":"15","bookPage":"50"},{"text":"3. We exchange gifts. The words after the verb are gifts — N (noun).","slide":169,"shape":"6","bookPage":"50"},{"text":"4. I celebrate in the evening. The words after the verb are in the evening — P (prepositional phrase).","slide":170,"shape":"13","bookPage":"50"},{"text":"5. The festival is traditional. The words after the verb are traditional — A (adjective).","slide":170,"shape":"15","bookPage":"50"},{"text":"Example on the activity page: People in London celebrate New Year.Possible answer for photo a (Food): People buy traditional food.","slide":172,"shape":"17","bookPage":"51"},{"text":"Possible answer for photo b (A family meal): The family eat a meal together.","slide":172,"shape":"19","bookPage":"51"},{"text":"Possible answer for photo c (Graduation): The students are happy at their graduation.","slide":172,"shape":"6","bookPage":"51"},{"text":"1. In India, people celebrate the Magh Bihu festival.Prepositional phrase: In India; object: the Magh Bihu festival.","slide":176,"shape":"16","bookPage":"51"},{"text":"2. Children sometimes clean their bedrooms on Mother’s Day.Prepositional phrase: on Mother’s Day; object: their bedrooms.","slide":176,"shape":"18","bookPage":"51"},{"text":"3. Children often have parties at school.Prepositional phrase: at school; object: parties.","slide":176,"shape":"6","bookPage":"51"},{"text":"4. On Saturday, we will watch the parade.Prepositional phrase: On Saturday; object: the parade.","slide":177,"shape":"11","bookPage":"51"},{"text":"a. Janadriyah is a cultural festival in Saudi Arabia. — 2","slide":180,"shape":"13","bookPage":"52"},{"text":"b. It is a very noisy city. — 1","slide":180,"shape":"15","bookPage":"52"},{"text":"c. People watch the camel-racing event. — 2","slide":180,"shape":"6","bookPage":"52"},{"text":"d. In the summer, it is very hot. — 1","slide":180,"shape":"8","bookPage":"52"},{"text":"e. It happens in February or March. — 2","slide":181,"shape":"13","bookPage":"52"},{"text":"f. I live in Taipei. — 1","slide":181,"shape":"15","bookPage":"52"},{"text":"g. There are lots of shops and restaurants. — 1","slide":181,"shape":"6","bookPage":"52"},{"text":"h. People listen to traditional poetry. — 2","slide":181,"shape":"8","bookPage":"52"},{"text":"i. It’s a great place to live. — 1","slide":182,"shape":"13","bookPage":"52"},{"text":"Completed Paragraph 1 — a city: I live in Taipei. It is a very noisy city. In the summer, it is very hot. There are lots of shops and restaurants. It’s a great place to live.","slide":182,"shape":"15","bookPage":"52"},{"text":"Completed Paragraph 2 — a festival: Janadriyah is a cultural festival in Saudi Arabia. It happens in February or March. People watch the camel-racing event. People listen to traditional poetry.","slide":182,"shape":"6","bookPage":"52"},{"text":"When I was a child, my classmates and I always celebrated International Teacher’s Day. — T (topic sentence)","slide":185,"shape":"16","bookPage":"52"},{"text":"It was my favourite day of the year. — S (supporting sentence)","slide":185,"shape":"18","bookPage":"52"},{"text":"We brought gifts for our teacher. — S (supporting sentence)","slide":185,"shape":"6","bookPage":"52"},{"text":"We ate special food and we usually played games. — S (supporting sentence)","slide":185,"shape":"8","bookPage":"52"},{"text":"The teachers loved Teacher’s Day and the students loved it, too. — S (supporting sentence)","slide":186,"shape":"16","bookPage":"52"},{"text":"To summarize, I have very special memories of Teacher’s Day. — C (concluding sentence)","slide":186,"shape":"18","bookPage":"52"},{"text":"Exercise 3a. Holi usually lasts for two days and people laugh, have fun and forget their troubles. — S (supporting sentence)","slide":190,"shape":"16","bookPage":"53"},{"text":"Exercise 3b. Holi is an ancient festival that celebrates the beginning of spring. — S (supporting sentence)","slide":190,"shape":"18","bookPage":"53"},{"text":"Exercise 3c. India celebrates the Festival of Colours, also known as Holi. — T (topic sentence)","slide":190,"shape":"6","bookPage":"53"},{"text":"Exercise 3d. In conclusion, this festival is an interesting Indian celebration. — C (concluding sentence)","slide":191,"shape":"10","bookPage":"53"},{"text":"Exercise 3e. During this festival, friends and family get together and throw coloured water and powder at each other – this activity celebrates the beautiful colours that come with spring. — S (supporting sentence)","slide":191,"shape":"12","bookPage":"53"},{"text":"Exercise 4a. Holi usually lasts for two days and people laugh, have fun and forget their troubles. Details and examples: lasts for two days; laugh, have fun and forget their troubles.","slide":192,"shape":"10","bookPage":"53"},{"text":"Exercise 4b. Holi is an ancient festival that celebrates the beginning of spring. Details and examples: ancient; celebrates the beginning of spring.","slide":192,"shape":"12","bookPage":"53"},{"text":"Exercise 4e. During this festival, friends and family get together and throw coloured water and powder at each other – this activity celebrates the beautiful colours that come with spring. Details and example: Friends and family get together and throw coloured water and powder at each other; this celebrates the colours of spring.","slide":193,"shape":"10","bookPage":"53"},{"text":"Exercise 5. Correct paragraph order: c, b, e, a, d.","slide":193,"shape":"12","bookPage":"53"},{"text":"Completed Holi paragraph: India celebrates the Festival of Colours, also known as Holi. Holi is an ancient festival that celebrates the beginning of spring. During this festival, friends and family get together and throw coloured water and powder at each other – this activity celebrates the beautiful colours that come with spring. Holi usually lasts for two days and people laugh, have fun and forget their troubles. In conclusion, this festival is an interesting Indian celebration.","slide":194,"shape":"11","bookPage":"53"},{"text":"Visitors can try local dishes at the market.","slide":199,"shape":"6","bookPage":null},{"text":"The event offers several activities in one place.","slide":199,"shape":"9","bookPage":null},{"text":"The boat race is the highlight of River Day. During the race, teams row past the park. People in the park cheer for those teams.","slide":200,"shape":"6","bookPage":null},{"text":"Our community fair brings neighbours together. Its shared meal gives them time to talk. These conversations help people get to know one another.","slide":201,"shape":"6","bookPage":null},{"text":"The decorated boats make this event interesting to watch. Several boats are visible on the water. I would like to see them from the riverbank. They could be the highlight of a riverside celebration.","slide":202,"shape":"7","bookPage":null},{"text":"The decorated boats are the highlight of this riverside festival. They make the water area look more interesting. Visitors can watch them from the bank. In conclusion, the boats give the event a memorable feature.","slide":203,"shape":"7","bookPage":null}];
